<?php require_once '../../conexion.php'; $datos = $pdo->query("SELECT dc.*, m.nombre as mat_nombre FROM detalle_compra dc LEFT JOIN materia_prima m ON dc.id_materia = m.ID ORDER BY dc.id_compra ASC")->fetchAll(PDO::FETCH_ASSOC); ?>
